import { useEffect, useState, type ReactNode } from "react";
import { Navigate, useLocation } from "react-router-dom";
import { getAuthToken, onAuthTokenChange, setAuthToken } from "./http";

/** Generated by AI Factory. The sign-in screen's route (from ui-spec). */
export const LOGIN_ROUTE = "/login";

/** Signed-in state that follows login/register (the generated client stores the token) and logout. */
export function useAuth(): { signedIn: boolean; signOut: () => void } {
  const [token, setToken] = useState(getAuthToken());
  useEffect(() => onAuthTokenChange(setToken), []);
  return { signedIn: Boolean(token), signOut: () => setAuthToken(undefined) };
}

/** Wraps routes whose API calls all need a token; sends signed-out users to LOGIN_ROUTE. */
export function RequireAuth({ children }: { children: ReactNode }) {
  const { signedIn } = useAuth();
  const location = useLocation();
  if (!signedIn && location.pathname !== LOGIN_ROUTE) {
    return <Navigate to={LOGIN_ROUTE} replace state={{ from: location.pathname }} />;
  }
  return <>{children}</>;
}
